mapper.select:

     {call PKG_MR_STRESS_TEST.p_get_factor_maxdrawdown2(
		#{p_factor_ids, jdbcType=VARCHAR, mode=IN},
		#{p_beginDate, jdbcType=DATE, mode=IN},
		#{p_endDate, jdbcType=DATE, mode=IN},
     	#{p_factor_cur,mode=OUT, jdbcType=CURSOR, resultMap=cursorMap1}
		)
	}

	select c1.param_value ftrTypeCode,
	       c2.param_value ftrType2Code,
	       a.ftr_id as ftrId,
	       case 
	         when length(a.ftr_id) > 20 then
				concat_ws('',(select ftr_name from stt_factor where ftr_id = SUBSTR (a.ftr_id,1,instr(a.ftr_id,'-')-1)),concat_ws('','-',
	           (select ftr_name from stt_factor where ftr_id = SUBSTR (a.ftr_id,instr(a.ftr_id,'-')+1))))
	         else (select ftr_name from stt_factor where ftr_id = a.ftr_id)
	       end as ftrName,
	       d1.param_value as startDate,
	       d2.param_value as endDate,
	       d3.param_value as days,
	       IFNULL(a.ftr_value, '数据未准备') as changeValue,
	       PKG_STRESS_TEST_COMM.FUNC_ASSET_TYPE_NAME(e1.param_value, e2.param_value, e3.param_value) as assetTypeName,
	       IF(!ISNULL(f1.param_value), 1, 0) as mixFtr,
	       f2.param_value as gradeCode
	  from stt_scene_factor a join stt_scene_ftrtips c1 on a.scene_ftr_id = c1.scene_ftr_id	
	       left join stt_scene_ftrtips c2 on a.scene_ftr_id = c2.scene_ftr_id	
	       left join stt_scene_ftrtips d1 on a.scene_ftr_id = d1.scene_ftr_id	
		   left join stt_scene_ftrtips d2 on a.scene_ftr_id = d2.scene_ftr_id	
		   left join stt_scene_ftrtips d3 on a.scene_ftr_id = d3.scene_ftr_id	
	       left join stt_scene_ftrtips e1 on a.scene_ftr_id = e1.scene_ftr_id	
	       left join stt_scene_ftrtips e2 on a.scene_ftr_id = e2.scene_ftr_id	
	       left join stt_scene_ftrtips e3 on a.scene_ftr_id = e3.scene_ftr_id	
		   left join stt_scene_ftrtips f1 on a.scene_ftr_id = f1.scene_ftr_id	
		   left join stt_scene_ftrtips f2 on a.scene_ftr_id = f2.scene_ftr_id	
	 where c1.dict_code = #{ftrRskType, jdbcType=VARCHAR}
	   and c2.dict_code = #{ftrRskType2, jdbcType=VARCHAR}
	   and d1.param_code = #{paramDateType, jdbcType=VARCHAR}
	   and d1.dict_code = #{startDateCode, jdbcType=VARCHAR}
	   and d2.param_code = #{paramDateType, jdbcType=VARCHAR}
	   and d2.dict_code = #{endDateCode, jdbcType=VARCHAR}
	   and d3.param_code = #{paramNumberType, jdbcType=VARCHAR}
	   and d3.dict_code = #{daysCode, jdbcType=VARCHAR}
	   and e1.param_code = '04'
	   and e1.dict_code = 'ASSETTYPE1'
	   and e2.param_code = '04'
	   and e2.dict_code = 'ASSETTYPE2'
	   and e3.param_code = '04'
	   and e3.dict_code = 'ASSETTYPE3'
	   and f1.param_code = #{paramNumberType, jdbcType=VARCHAR}
	   and f1.dict_code = #{mixCode, jdbcType=VARCHAR}
	   and f2.param_code = '04'
	   and f2.dict_code = #{gradeCode, jdbcType=VARCHAR}

       	   and a.scene_id =#{sceneId, jdbcType=VARCHAR}
